def count(mult, C=0, H=0, O=0):
    return {'C': mult*C, 'H': mult*H, 'O': mult*O}

def add(a, b):
    return {k: a.get(k,0)+b.get(k,0) for k in set(a)|set(b)}

options = {
 'A': ({'L': add(count(1,O=2), count(1,H=2)), 'R': add(count(1,C=6,H=12,O=6), count(1,C=1,O=2))}),
 'B': ({'L': add(count(1,C=1,O=2), count(1,H=2,O=1)), 'R': add(count(1,C=6,H=6,O=3), count(1,O=2))}),
 'C': ({'L': add(count(6,O=2), count(6,H=2,O=1)), 'R': add(count(1,C=6,H=12,O=6), count(6,C=1,O=2))}),
 'D': ({'L': add(count(6,C=1,O=2), count(6,H=2,O=1)), 'R': add(count(1,C=6,H=12,O=6), count(6,O=2))}),
}

for k,v in options.items():
    L, R = v['L'], v['R']
    print(k, 'left', L, 'right', R, 'balanced' if L==R else 'NOT balanced')
