planets = {"Venus (B)": 0.723, "Earth (A)": 1.000, "Jupiter (C)": 5.203, "Neptune (D)": 30.07}

results = {name: a**1.5 for name, a in planets.items()}
for name, T in sorted(results.items(), key=lambda kv: kv[1]):
    print(f"{name:14s} a = {planets[name]:6.3f} AU   T = {T:9.2f} Earth years")

longest = max(results, key=results.get)
print("\nLongest year:", longest, f"({results[longest]:.1f} Earth years)")

# sanity check against published values
published = {"Venus": 0.615, "Earth": 1.0, "Jupiter": 11.86, "Neptune": 164.8}
print("\nPublished sidereal periods (Earth years):", published)
print("Kepler vs published ratio check:")
for name, a in planets.items():
